/*
 * A238008  Numbers n such that n*(n+3)*(n+6) is a triangular number.
 * https://oeis.org/A238008
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, fini, full
 * Formula:   not stated
 * Range:     i8 none, i16 n <= 4, i32 n <= 8, i64 n <= 11, i128 n <= 11,
 *            big any n
 * Helpers:   floor_sqrt, seq_alloc_new_array, seq_free_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A238008 – Numbers n such that n*(n+3)*(n+6) is a triangular number.
 * The sequence is generated by brute‑force search starting from n = -5
 * and testing each successive integer.  Terms are cached for reuse. */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

#include "../utils/floor_sqrt.h"
#include "../utils/seq_alloc_new_array.h"
#include "../utils/seq_free_array.h"

/* Cache for already found terms. */
static seq_t *cache      = NULL;   /* array of terms */
static size_t cache_len  = 0;      /* number of stored terms   */
static size_t cache_cap  = 0;      /* allocated capacity      */
static seq_t next_candidate = -5; /* next integer to test    */

/* Ensure the cache can hold at least `min_cap` elements. */
static void ensure_cache_capacity(size_t min_cap)
{
    if (min_cap <= cache_cap)
        return;
    /* Allocate new buffer with at least min_cap slots, doubling each time. */
    size_t new_cap = (cache_cap == 0) ? 8 : cache_cap;
    while (new_cap < min_cap)
        new_cap <<= 1;
    seq_t *new_mem = seq_alloc_new_array(new_cap);
    for (size_t i = 0; i < cache_len; ++i)
        new_mem[i] = cache[i];   /* assignment is fine for constructed objects */
    seq_free_array(cache);
    cache = new_mem;
    cache_cap = new_cap;
}

/* Test whether n*(n+3)*(n+6) is a triangular number. */
static bool is_triangular_n(seq_t n)
{
    seq_t m = n * (n + 3) * (n + 6);
    if (m < 0)
        return false;    /* triangular numbers are non‑negative */
    seq_t s = 8 * m + 1;
    seq_t r = floor_sqrt(s);
    return r * r == s;
}

/* Return the n-th term of the sequence (1‑based). */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;  /* undefined by OEIS offset; return 0 as sentinel */

    /* Grow the cache until we have at least n terms. */
    while (cache_len < (size_t)n) {
        if (is_triangular_n(next_candidate)) {
            ensure_cache_capacity(cache_len + 1);
            cache[cache_len++] = next_candidate;
        }
        ++next_candidate;
    }
    return cache[(size_t)n - 1];
}
